// ========================================
// 6. FINAL VALIDATION
// ========================================

console.log('\n📊 Final Status:');
console.log('━'.repeat(70));

if (tablesExist) {
  const { count: signalCount } = await supabase
    .from('intervention_signals')
    .select('id', { count: 'exact' })
    .limit(0);

  const { count: recCount } = await supabase
    .from('intervention_recommendations')
