        ?? `${canonBaseBuild}-${gitShortHash}`;
    const buildTimestamp = process.env.VSM_BUILD_TIMESTAMP ?? new Date().toISOString();

    return {
        canonBaseBuild,
        gitShortHash,
        runtimeBuildFingerprint,
        buildTimestamp,
    };
}

