def load_adapter(self, adapter_path: str | Path, adapter_id: str = "") -> None:
        """Load a LoRA adapter onto the base model."""
        self._load_base()

        try:
            from peft import PeftModel

            self._base_model = PeftModel.from_pretrained(
                self._base_model,
                str(adapter_path),
            )
