                if content.strip():
                    parts.append(f"File content:\n{content}")
            except Exception:
                pass

        parts.append(f"Query: {query}")

if context:
            parts.append("Neighbor messages:")
            for msg in context:
                parts.append(msg.to_prompt_context())

        prompt = "\n\n".join(parts)
        return await self.backend.generate(
            prompt,
            max_tokens=self.max_tokens,
            temperature=self.temperature,
        )

def __getattr__(name: str):
    if name == "LocalModel":
        from graqle.backends.local import LocalModel
        return LocalModel
    if name in ("AnthropicBackend", "OpenAIBackend", "BedrockBackend",
                "OllamaBackend", "CustomBackend"):
        from graqle.backends import api
        return getattr(api, name)
    if name == "GeminiBackend":
        from graqle.backends.gemini import GeminiBackend
        return GeminiBackend
    if name in ("create_provider_backend", "PROVIDER_PRESETS",
                "get_provider_names"):
        from graqle.backends import providers
        return getattr(providers, name)
    raise AttributeError(f"module 'graqle.backends' has no attribute {name!r}")

class BackendError(Exception):
    """Raised when a backend call fails after all retries."""

    def __init__(self, backend_name: str, message: str, attempts: int = 0) -> None:
        self.backend_name = backend_name
        self.attempts = attempts
        super().__init__(f"[{backend_name}] {message} (after {attempts} attempts)")

async def _retry_with_backoff(
    func, *, backend_name: str, max_retries: int = MAX_RETRIES
) -> Any:
    """Execute an async function with exponential backoff retry."""
    last_error = None
    for attempt in range(max_retries):
        try:
            return await func()
        except ImportError:
            raise  # Don't retry import errors
        except Exception as e:
            last_error = e
            if attempt < max_retries - 1:
                delay = min(BASE_DELAY * (2 ** attempt), MAX_DELAY)
                logger.warning(
                    f"[{backend_name}] Attempt {attempt + 1}/{max_retries} failed: {e}. "
                    f"Retrying in {delay:.1f}s..."
                )
                await asyncio.sleep(delay)
            else:
                logger.error(
                    f"[{backend_name}] All {max_retries} attempts failed: {e}"
                )

    raise BackendError(backend_name, str(last_error), max_retries)

