\\textbf{{Method}} & \\textbf{{EM}} & \\textbf{{F1}} & \\textbf{{Lat. (ms)}} & \\textbf{{Tokens}} & \\textbf{{Rounds}} & \\textbf{{Nodes}} & \\textbf{{Cost}} \\\\
\\midrule
{chr(10).join(rows)}
\\bottomrule
\\end{{tabular}}
\\end{{table}}"""

    return table

