            "properties(n) AS properties"
        )
        self._edge_query = edge_query or (
            "MATCH (a:CogniNode)-[r]->(b:CogniNode) RETURN "
            "r.id AS id, "
            "a.id AS source, "
            "b.id AS target, "
            "type(r) AS relationship, "
            "properties(r) AS properties"
        )

