        except (json.JSONDecodeError, OSError):
            return []

def save_declaration(self, declaration: ScopeDeclaration) -> None:
        """Persist a scope declaration to disk."""
        self._ensure_dir()
        safe_name = declaration.task.replace(" ", "_").lower()[:50]
        fpath = self.scope_dir / f"{safe_name}.json"
        fpath.write_text(
            json.dumps(declaration.model_dump(), indent=2, default=str),
            encoding="utf-8",
        )

    def load_declaration(self, task_name: str) -> ScopeDeclaration | None:
        """Load a scope declaration from disk."""
        safe_name = task_name.replace(" ", "_").lower()[:50]
        fpath = self.scope_dir / f"{safe_name}.json"
        if not fpath.exists():
            return None
        data = json.loads(fpath.read_text(encoding="utf-8"))
        return ScopeDeclaration(**data)

    def _load_default_rules(self) -> list[ScopeRule]:
        """Load default scope rules from .graqle/governance/scope/default.json."""
        fpath = self.scope_dir / "default.json"
        if not fpath.exists():
            return []
        try:
            data = json.loads(fpath.read_text(encoding="utf-8"))
            return [ScopeRule(**r) for r in data.get("rules", [])]
        except (json.JSONDecodeError, OSError):
            return []

def has_header(file_path: Path) -> bool:
    """Check if a file already has an intelligence header."""
    try:
        content = file_path.read_text(encoding="utf-8")
    except OSError:
        return False

    ext = file_path.suffix.lower()
    if ext not in _MARKERS:
        return False

    _, open_marker, _ = _MARKERS[ext]
    return open_marker in content

def _find_insert_position(content: str, ext: str) -> int:
    """Find the best position to insert the header.

    For Python: after shebang, encoding declaration, and module docstring.
    For JS/TS: after any 'use strict' or initial comments.
    """
    pos = 0

    if ext == ".py":
        lines = content.split("\n")
        line_idx = 0

        # Skip shebang
        if lines and lines[0].startswith("#!"):
            line_idx = 1

        # Skip encoding declaration
        if line_idx < len(lines) and "coding" in lines[line_idx]:
            line_idx += 1

        # Skip blank lines
        while line_idx < len(lines) and not lines[line_idx].strip():
            line_idx += 1

        # Skip module docstring
        if line_idx < len(lines):
            line = lines[line_idx].strip()
            if line.startswith('"""') or line.startswith("'''"):
                quote = line[:3]
                if line.count(quote) >= 2 and len(line) > 6:
                    # Single-line docstring
                    line_idx += 1
                else:
                    # Multi-line docstring — find closing
                    line_idx += 1
                    while line_idx < len(lines) and quote not in lines[line_idx]:
                        line_idx += 1
                    if line_idx < len(lines):
                        line_idx += 1  # skip closing line

def has_header(file_path: Path) -> bool:
