                    ))

    return insights

def _detect_missing_rate_limits(
    all_units: list[FileIntelligenceUnit],
) -> list[CuriosityInsight]:
    """Detect API route modules that define routes but have no rate limiting."""
    insights: list[CuriosityInsight] = []
    module_has_routes: dict[str, bool] = {}
    module_has_rate_limit: dict[str, bool] = {}

    for module, file_path, text in _iter_chunk_texts(all_units):
        if _is_test_file(file_path):
            continue

        for pat_name, pattern in _RATE_LIMIT_PATTERNS:
            if pattern.search(text):
                if pat_name == "route_definition":
                    module_has_routes[module] = True
                elif pat_name == "has_rate_limit":
                    module_has_rate_limit[module] = True

    for module in module_has_routes:
        if not module_has_rate_limit.get(module, False):
            insights.append(CuriosityInsight(
                category=InsightCategory.INVARIANT,
                module=module,
                message="Missing rate limit: module defines API routes but no rate limiting detected — consider adding throttling",
                metric="0 rate limits",
                severity="info",
            ))

    return insights

def _detect_open_cors(
    all_units: list[FileIntelligenceUnit],
) -> list[CuriosityInsight]:
    """Detect wildcard CORS configuration (Access-Control-Allow-Origin: *)."""
    insights: list[CuriosityInsight] = []
    seen: set[str] = set()

    for module, file_path, text in _iter_chunk_texts(all_units):
        if _is_test_file(file_path):
            continue

        for _cors_type, pattern in _CORS_PATTERNS:
            if pattern.search(text):
                if module not in seen:
                    seen.add(module)
                    insights.append(CuriosityInsight(
                        category=InsightCategory.INVARIANT,
                        module=module,
                        message="Open CORS wildcard: allows all origins — restrict to specific domains in production",
                        metric="wildcard origin",
                        severity="warn",
                    ))

    return insights

def _detect_insecure_http(
    all_units: list[FileIntelligenceUnit],
) -> list[CuriosityInsight]:
    """Detect HTTP URLs pointing to non-localhost hosts (should be HTTPS)."""
    insights: list[CuriosityInsight] = []
    seen: set[str] = set()

    for module, file_path, text in _iter_chunk_texts(all_units):
        if _is_test_file(file_path):
            continue

        for url in _INSECURE_HTTP_PATTERN.findall(text):
            dedup_key = f"{module}:{url[:50]}"
            if dedup_key not in seen:
                seen.add(dedup_key)
                insights.append(CuriosityInsight(
                    category=InsightCategory.INVARIANT,
                    module=module,
                    message=f"Insecure HTTP: '{url}' uses HTTP instead of HTTPS — data in cleartext",
                    metric="http",
                    severity="warn",
                ))

    return insights

def _detect_exposed_env_vars(
    all_units: list[FileIntelligenceUnit],
) -> list[CuriosityInsight]:
    """Detect environment variables being logged or exposed in responses."""
    insights: list[CuriosityInsight] = []
    seen: set[str] = set()

    for module, file_path, text in _iter_chunk_texts(all_units):
        if _is_test_file(file_path):
            continue

        for exp_type, pattern in _EXPOSED_ENV_PATTERNS:
            if pattern.search(text):
                dedup_key = f"{module}:{exp_type}"
                if dedup_key not in seen:
                    seen.add(dedup_key)
                    insights.append(CuriosityInsight(
                        category=InsightCategory.INVARIANT,
                        module=module,
                        message=f"Exposed env vars: {exp_type} — environment variables may leak via logs or responses",
                        metric=exp_type,
                        severity="critical",
                    ))

    return insights

class LearningTracker:
    """Tracks learning events and recompile history for dashboard."""

    def __init__(self, root: Path | None = None) -> None:
        self.root = root or Path(".")
        self._path = self.root / ".graqle" / "learning_log.json"

    def _load(self) -> dict[str, Any]:
        if self._path.exists():
            try:
                return json.loads(self._path.read_text(encoding="utf-8"))
            except Exception:
                pass
        return {
            "total_learning_events": 0,
            "total_recompiles": 0,
            "domain_counts": {},
            "skill_activations": {},
            "events": [],
        }

    def _save(self, data: dict[str, Any]) -> None:
        self._path.parent.mkdir(parents=True, exist_ok=True)
        self._path.write_text(json.dumps(data, indent=2), encoding="utf-8")

    def record_learn_event(
        self,
        *,
        event_type: str = "node",
        node_id: str = "",
        entity_type: str = "",
        domain: str = "",
        edges_added: int = 0,
        description: str = "",
    ) -> None:
        """Record a graq learn event."""
        data = self._load()
        data["total_learning_events"] += 1

        # Classify domain from entity type if not provided
        if not domain:
            domain = self._classify_domain(entity_type)

        data["domain_counts"][domain] = data["domain_counts"].get(domain, 0) + 1

@staticmethod
    def _classify_domain(entity_type: str) -> str:
        """Auto-classify entity type into a domain."""
        et = entity_type.upper()
        eng_types = {
            "MODULE", "CLASS", "FUNCTION", "COMPONENT", "LAMBDA", "CONTAINER",
            "DATABASE", "SCHEMA", "API", "ENDPOINT", "SERVICE", "TEST",
            "REACTCOMPONENT", "APIENDPOINT", "MIDDLEWARE",
        }
        gov_types = {
            "REGULATION", "POLICY", "GOV_FRAMEWORK", "GOV_REQUIREMENT",
            "GOV_CONTROL", "GOV_ENFORCEMENT", "GOV_EVIDENCE",
        }
        mkt_types = {"SEGMENT", "CHANNEL", "CAMPAIGN", "MESSAGE", "COHORT"}
        fin_types = {"INSTRUMENT", "PORTFOLIO", "TRANSACTION", "RISK_METRIC"}
        legal_types = {"CONTRACT", "CLAUSE", "OBLIGATION", "JURISDICTION"}

        if et in eng_types:
            return "engineering"
        if et in gov_types:
            return "governance"
        if et in mkt_types:
            return "marketing"
        if et in fin_types:
            return "financial"
        if et in legal_types:
            return "legal"
        return "general"

@staticmethod
    def _skill_domain(skill_name: str) -> str:
        """Map skill name to domain."""
        sn = skill_name.lower()
        if any(k in sn for k in ("react", "css", "ui", "frontend", "component")):
