            elif stripped.startswith("## [HIGH]"):
                current_severity = "HIGH"
            elif stripped.startswith("## [MEDIUM]"):
                current_severity = "MEDIUM"
            elif stripped.startswith("## Recently Added"):
                current_severity = "MEDIUM"
            elif stripped.startswith("## Archived"):
                current_severity = "LOW"

            # Parse lesson lines
