        for entity in self._entities:
            new_edges = self._infer_for_entity(entity)
            for edge in new_edges:
                key = (edge.source_id, edge.target_id, edge.relationship)
                if key not in seen:
                    seen.add(key)
                    edges.append(edge)

        return edges

