                # Look for patent entity
                for e in self._entities:
                    if e.node_type == "PATENT":
                        edges.append(ExtractedEdge(
                            source_id=entity.id,
                            target_id=e.id,
                            relationship="COVERED_BY",
                            confidence=0.85,
                            source_file=entity.source_file,
                        ))
                        break

