def _normalize_keys(d: dict[str, Any]) -> dict[str, Any]:
    """Convert camelCase config keys to snake_case."""
    result = {}
    for k, v in d.items():
        snake = re.sub(r'(?<!^)(?=[A-Z])', '_', k).lower()
        if isinstance(v, dict):
            v = _normalize_keys(v)
        result[snake] = v
    return result

