# Category → (module_path, class_name)
_EXTRACTOR_MAP: dict[str, tuple[str, str]] = {
    "DEPENDENCY_MANIFEST": (
        "graqle.scanner.extractors.dependency",
        "DependencyExtractor",
    ),
    "API_SPEC": (
        "graqle.scanner.extractors.api_spec",
        "APISpecExtractor",
    ),
    "INFRA_CONFIG": (
        "graqle.scanner.extractors.infra",
        "InfraExtractor",
    ),
