def _heading_level(line: str, next_line: str | None) -> int:
    """Return a heading level for *line* (1 or 2).

    * ALL-CAPS headings → level 1
    * ``===`` underline → level 1
    * ``---`` / ``~~~`` / ``^^^`` underline → level 2
