                    risk_map[fp.replace("\\", "/")] = rl
            except Exception:
                continue

risk_colors = {
        "CRITICAL": "#ef4444",
        "HIGH": "#f97316",
        "MEDIUM": "#eab308",
        "LOW": "#22c55e",
    }

    nodes_out = []
    for nid in selected_ids:
        if nid not in graph.nodes:
            continue
        node = graph.nodes[nid]
        deg = degree_map.get(nid, 0)

