      setConcepts(prev => prev.map(c => c.id === expandedConcept ? { ...c, relation_count: (c.relation_count || 0) + 1 } : c));
    } catch (error: any) {
      toast.error(error.message || 'Error al crear relacion (posible duplicado)');
    }
  };

{!isAddingRelation && (
