    if (deal.sold_count >= deal.max_qty) return { label: 'Agotada', cls: 'bg-amber-500/10 text-amber-400 ring-amber-500/20' };
    return { label: 'En vivo', cls: 'bg-emerald-500/10 text-emerald-400 ring-emerald-500/20' };
}

