    onCoverChange?: (url: string | null) => void;
}

export function ImageUploader({ images, coverImage, onChange, onCoverChange }: ImageUploaderProps) {
    const [uploading, setUploading] = useState(false);
    const [uploadCount, setUploadCount] = useState(0);
    const [dragOver, setDragOver] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showUrlInput, setShowUrlInput] = useState(false);
    const [urlInput, setUrlInput] = useState('');
    const fileRef = useRef<HTMLInputElement>(null);

    const handleFiles = useCallback(async (files: FileList | File[]) => {
        const fileArray = Array.from(files);
        if (fileArray.length === 0) return;

        setError(null);
        setUploading(true);
        setUploadCount(fileArray.length);

        const newUrls: string[] = [];
        const errors: string[] = [];

        for (const file of fileArray) {
            try {
                // 1. Optimizar imagen (Client-side)
                const processedFile = await processImageForUpload(file);
                // 2. Subir a Supabase
                const url = await uploadProductImage(processedFile);
                newUrls.push(url);
            } catch (err) {
                errors.push(err instanceof Error ? err.message : `Error con ${file.name}`);
            }
        }

if (newUrls.length > 0) {
            // Priority 1: Newly uploaded images go at the START
            onChange([...newUrls, ...images]);
            // If no cover image exists, the first of the new ones becomes cover
            if (!coverImage && onCoverChange) {
                if (newUrls[0]) onCoverChange(newUrls[0]);
            }
        }
        if (errors.length > 0) {
            setError(errors.join('. '));
        }

        setUploading(false);
        setUploadCount(0);
    }, [images, onChange, coverImage, onCoverChange]);

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setDragOver(false);
        if (e.dataTransfer.files.length > 0) {
            handleFiles(e.dataTransfer.files);
        }
    }, [handleFiles]);

    const handleRemove = async (url: string) => {
        onChange(images.filter((u) => u !== url));
        if (coverImage === url && onCoverChange) {
            onCoverChange(null);
        }
        // Fire-and-forget: try to delete from storage
        deleteProductImage(url).catch(() => { });
    };

    const handleAddUrl = () => {
        const u = urlInput.trim();
        if (u) {
            onChange([u, ...images]); // Prepend manually added URLs too
            if (!coverImage && onCoverChange) {
                onCoverChange(u);
            }
            setUrlInput('');
            setShowUrlInput(false);
        }
    };

{/* Error Message */}
