interface LoginFormProps {
    onSuccess?: () => void;
    onSwitchToSignUp?: () => void;
}

export function LoginForm({ onSuccess, onSwitchToSignUp }: LoginFormProps) {
    const { signIn, resetPassword } = useAuth();

    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [resetSent, setResetSent] = useState(false);
    const [resetLoading, setResetLoading] = useState(false);

    // Rate limiting: exponential backoff on failed attempts
    const [failedAttempts, setFailedAttempts] = useState(0);
    const [lockedUntil, setLockedUntil] = useState(0);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        // Check rate limit lockout
        const now = Date.now();
        if (lockedUntil > now) {
            const secsLeft = Math.ceil((lockedUntil - now) / 1000);
            setError(`Demasiados intentos. Espera ${secsLeft}s`);
            return;
        }

        if (!email.trim() || !password.trim()) {
            setError('Completa todos los campos');
            return;
        }

        try {
            setLoading(true);
            await signIn(email, password);
            setFailedAttempts(0);
            onSuccess?.();
        } catch (err: unknown) {
            const newAttempts = failedAttempts + 1;
            setFailedAttempts(newAttempts);

// Exponential backoff: 2s, 4s, 8s, 16s, max 30s
            if (newAttempts >= 3) {
                const delay = Math.min(Math.pow(2, newAttempts) * 1000, 30_000);
                setLockedUntil(Date.now() + delay);
            }

            const message = err instanceof Error ? err.message : 'Error al iniciar sesión';
            if (message.includes('Invalid login credentials')) {
                setError('Email o contraseña incorrectos');
            } else {
                setError('Error al iniciar sesión. Intenta de nuevo.');
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-5">
            <div className="text-center mb-6">
                <h2 className="text-2xl font-bold text-theme-primary">Iniciar sesión</h2>
                <p className="mt-1 text-sm text-theme-secondary">Bienvenido de vuelta a VSM Store</p>
            </div>

            {error && (
                <div className="rounded-lg bg-red-500/10 border border-red-500/20 px-4 py-3 text-sm text-red-400">
                    {error}
                </div>
            )}

{/* Forgot password */}
            <div className="text-right">
                {resetSent ? (
                    <span className="text-xs text-emerald-400 flex items-center justify-end gap-1">
                        <Mail className="h-3 w-3" /> Revisa tu email
                    </span>
                ) : (
                    <button
                        type="button"
                        disabled={resetLoading || !email.trim()}
                        onClick={async () => {
                            try {
                                setResetLoading(true);
                                await resetPassword(email);
                                setResetSent(true);
                            } catch {
                                setError('No se pudo enviar el email de recuperación');
                            } finally {
                                setResetLoading(false);
                            }
                        }}
                        className="text-xs text-vape-400 hover:text-vape-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {resetLoading ? 'Enviando...' : '¿Olvidaste tu contraseña?'}
                    </button>
                )}
            </div>

{/* Submit */}
            <button
                type="submit"
                disabled={loading}
                className={cn(
                    'flex w-full items-center justify-center gap-2 rounded-xl py-3.5 text-sm font-semibold text-white shadow-lg transition-all',
                    'bg-vape-500 hover:bg-vape-600 shadow-vape-500/25 hover:shadow-vape-500/40',
                    'hover:-translate-y-0.5 active:translate-y-0',
                    'disabled:opacity-60 disabled:cursor-not-allowed disabled:hover:translate-y-0'
                )}
            >
                {loading ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                    <LogIn className="h-4 w-4" />
                )}
                {loading ? 'Ingresando...' : 'Iniciar sesión'}
            </button>

{/* Switch to signup */}
            <p className="text-center text-sm text-theme-secondary">
                ¿No tienes cuenta?{' '}
                {onSwitchToSignUp ? (
                    <button
                        type="button"
                        onClick={onSwitchToSignUp}
                        className="font-medium text-vape-400 hover:text-vape-300 transition-colors"
                    >
                        Crear cuenta
                    </button>
                ) : (
                    <Link to="/signup" className="font-medium text-vape-400 hover:text-vape-300 transition-colors">
                        Crear cuenta
                    </Link>
                )}
            </p>
        </form>
    );
}

