interface SignUpFormProps {
    onSuccess?: () => void;
    onSwitchToLogin?: () => void;
}

export function SignUpForm({ onSuccess, onSwitchToLogin }: SignUpFormProps) {
    const { signUp } = useAuth();

    const [fullName, setFullName] = useState('');
    const [email, setEmail] = useState('');
    const [phone, setPhone] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [acceptTerms, setAcceptTerms] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);

    const validate = (): string | null => {
        if (!fullName.trim()) return 'Ingresa tu nombre completo';
        if (!email.trim()) return 'Ingresa tu email';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return 'Email no válido';
        if (password.length < 8) return 'La contraseña debe tener mínimo 8 caracteres';
        if (!/[A-Z]/.test(password)) return 'La contraseña debe incluir al menos una mayúscula';
        if (!/[0-9]/.test(password)) return 'La contraseña debe incluir al menos un número';
        if (password !== confirmPassword) return 'Las contraseñas no coinciden';
        if (!acceptTerms) return 'Debes aceptar los términos y condiciones';
        return null;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

const validationError = validate();
        if (validationError) {
            setError(validationError);
            return;
        }

        try {
            setLoading(true);
            await signUp(email, password, fullName, phone || undefined);
            setSuccess(true);
            onSuccess?.();
        } catch (err: unknown) {
            const message = err instanceof Error ? err.message : '';
            if (message.includes('already registered')) {
                setError('Este email ya está registrado');
            } else {
                setError('Error al crear cuenta. Intenta de nuevo.');
            }
        } finally {
            setLoading(false);
        }
    };

    if (success) {
        return (
            <div className="text-center space-y-4 py-8">
                <span className="text-5xl">📧</span>
                <h2 className="text-xl font-bold text-theme-primary">¡Cuenta creada!</h2>
                <p className="text-sm text-theme-secondary max-w-xs mx-auto">
                    Revisa tu email para confirmar tu cuenta. Puedes cerrar esta ventana.
                </p>
            </div>
        );
    }

const inputClasses = (hasError: boolean) => cn(
        'w-full rounded-xl border bg-theme-secondary/20 px-4 py-3 text-sm text-theme-primary placeholder-theme-secondary/50',
        'outline-none transition-all focus:ring-2',
        hasError ? 'border-red-500/50 focus:ring-red-500/30' : 'border-theme focus:border-vape-500 focus:ring-vape-500/20'
    );

    return (
        <form onSubmit={handleSubmit} className="space-y-4">
            <div className="text-center mb-4">
                <h2 className="text-2xl font-bold text-theme-primary">Crear cuenta</h2>
                <p className="mt-1 text-sm text-theme-secondary">Únete a VSM Store</p>
            </div>

            {error && (
                <div className="rounded-lg bg-red-500/10 border border-red-500/20 px-4 py-3 text-sm text-red-400">
                    {error}
                </div>
            )}

            {/* Nombre completo */}
            <div>
                <label htmlFor="signup-name" className="block text-sm font-medium text-theme-secondary mb-1.5">
                    Nombre completo *
                </label>
                <input
                    id="signup-name"
                    type="text"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    placeholder="Juan Pérez"
                    className={inputClasses(!!error && !fullName.trim())}
                />
            </div>

{/* Password */}
            <div>
                <label htmlFor="signup-password" className="block text-sm font-medium text-theme-secondary mb-1.5">
                    Contraseña * <span className="text-theme-secondary/70 font-normal">(mín. 8 caracteres, 1 mayúscula, 1 número)</span>
                </label>
                <div className="relative">
                    <input
                        id="signup-password"
                        type={showPassword ? 'text' : 'password'}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="••••••••"
                        className={cn(inputClasses(!!error && password.length < 6), 'pr-11')}
                    />
                    <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-theme-secondary hover:text-theme-primary transition-colors"
                    >
                        {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                </div>
            </div>

{/* Confirm password */}
            <div>
                <label htmlFor="signup-confirm" className="block text-sm font-medium text-theme-secondary mb-1.5">
                    Confirmar contraseña *
                </label>
                <input
                    id="signup-confirm"
                    type={showPassword ? 'text' : 'password'}
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    placeholder="••••••••"
                    className={inputClasses(!!error && password !== confirmPassword && confirmPassword.length > 0)}
                />
            </div>

{/* Terms */}
            <label className="flex items-start gap-2.5 cursor-pointer">
                <input
                    type="checkbox"
                    checked={acceptTerms}
                    onChange={(e) => setAcceptTerms(e.target.checked)}
                    className="mt-0.5 h-4 w-4 rounded border-theme bg-theme-secondary/20 text-vape-500 focus:ring-vape-500/30"
                />
                <span className="text-xs text-theme-secondary leading-relaxed">
                    Acepto los{' '}
                    <Link to="/legal/terms" className="text-vape-400 hover:text-vape-300 underline" target="_blank">términos y condiciones</Link>
                    {' '}y la{' '}
                    <Link to="/legal/privacy" className="text-vape-400 hover:text-vape-300 underline" target="_blank">política de privacidad</Link>
                </span>
            </label>

{/* Submit */}
            <button
                type="submit"
                disabled={loading}
                className={cn(
                    'flex w-full items-center justify-center gap-2 rounded-xl py-3.5 text-sm font-semibold text-white shadow-lg transition-all',
                    'bg-vape-500 hover:bg-vape-600 shadow-vape-500/25 hover:shadow-vape-500/40',
                    'hover:-translate-y-0.5 active:translate-y-0',
                    'disabled:opacity-60 disabled:cursor-not-allowed disabled:hover:translate-y-0'
                )}
            >
                {loading ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                    <UserPlus className="h-4 w-4" />
                )}
                {loading ? 'Creando cuenta...' : 'Crear cuenta'}
            </button>

{/* Switch to login */}
            <p className="text-center text-sm text-theme-secondary">
                ¿Ya tienes cuenta?{' '}
                {onSwitchToLogin ? (
                    <button
                        type="button"
                        onClick={onSwitchToLogin}
                        className="font-medium text-vape-400 hover:text-vape-300 transition-colors"
                    >
                        Iniciar sesión
                    </button>
                ) : (
                    <Link to="/login" className="font-medium text-vape-400 hover:text-vape-300 transition-colors">
                        Iniciar sesión
                    </Link>
                )}
            </p>
        </form>
    );
}

