export const BottomNavigation = memo(function BottomNavigation() {
    const { pathname } = useLocation();
    const navigate = useNavigate();
    const cartCount = useCartStore((s) => s.items.reduce((acc, item) => acc + item.quantity, 0));
    const openSearch = useSearchOverlay((s) => s.open);
    const isCartOpen = useCartStore((s) => s.isOpen);
    const openCart = useCartStore((s) => s.openCart);
    const { trigger } = useHaptic();

    const scrollToPopular = () => {
        const tryScroll = (attempts = 0) => {
            const section = document.getElementById('mas-vendidos');
            if (section) {
                section.scrollIntoView({ behavior: 'smooth' });
            } else if (attempts < 10) {
                setTimeout(() => tryScroll(attempts + 1), 150);
            }
        };
        tryScroll();
    };

const navItems = [
        {
            label: 'Popular',
            icon: TrendingUp,
            href: '/#mas-vendidos',
            onClick: (e: React.MouseEvent) => {
                e.preventDefault();
                trigger('light');
                if (pathname === '/') {
                    scrollToPopular();
                } else {
                    navigate('/');
                    setTimeout(scrollToPopular, 300);
                }
            },
        },
        {
            label: 'Buscar',
            icon: Search,
            href: '#search',
            isActive: false,
            onClick: (e: React.MouseEvent) => {
                e.preventDefault();
                trigger('light');
                openSearch();
            },
        },
        {
            label: 'Carrito',
            icon: ShoppingCart,
            href: '#cart',
            isActive: isCartOpen,
            badge: cartCount > 0 ? cartCount : null,
            onClick: (e: React.MouseEvent) => {
                e.preventDefault();
                trigger('light');
                openCart();
            },
        },
        {
            label: 'Perfil',
            icon: User,
            href: '/profile',
            isActive: pathname === '/profile' || pathname === '/login',
            onClick: () => trigger('light'),
        },
    ];

return (
        <div className="fixed bottom-4 md:bottom-6 left-1/2 -translate-x-1/2 z-50 w-[calc(100%-2rem)] max-w-sm md:hidden pointer-events-none">
            <nav className="pointer-events-auto rounded-[2rem] border border-white/20 bg-[#0f172a]/80 backdrop-blur-3xl shadow-[0_20px_40px_-15px_rgba(0,0,0,0.7)] pb-safe-offset">
            <div className="flex justify-around items-center h-16">
                {navItems.map((item) => (
                    <Link
                        key={item.label}
                        to={item.href}
                        onClick={item.onClick}
                        className={cn(
                            'relative flex flex-col items-center justify-center w-full h-full gap-1 transition-all active:scale-90',
                            item.isActive ? 'text-vape-400' : 'text-theme-secondary hover:text-theme-primary'
                        )}
                    >
                        <div className={cn(
                            'relative p-1.5 rounded-xl transition-all',
                            item.isActive && 'bg-vape-500/10'
                        )}>
                            <item.icon className={cn('h-6 w-6', item.isActive && 'fill-current')} strokeWidth={item.isActive ? 2.5 : 2} />

{/* Badge para carrito */}
                            {item.badge && (
                                <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-vape-500 text-[9px] font-bold text-white shadow-sm ring-2 ring-theme-primary animate-bounce-in">
                                    {item.badge > 9 ? '9+' : item.badge}
                                </span>
                            )}
                        </div>
                        <span className="text-xs font-medium tracking-wide">{item.label}</span>
                    </Link>
                ))}
            </div>
            </nav>
        </div>
    );
});

