}

export function MobileMenu({ isOpen, onClose }: MobileMenuProps) {
    const { isAuthenticated, user, signOut } = useAuth();
    const [isAdmin, setIsAdmin] = useState(false);
    const { data: vapeCategories = [] } = useCategories('vape');
    const { data: herbalCategories = [] } = useCategories('420');
    const menuRef = useRef<HTMLDivElement>(null);

    const vapeRoots = vapeCategories.filter((c) => c.parent_id === null);
    const herbalRoots = herbalCategories.filter((c) => c.parent_id === null);

    // Body scroll lock & Escape to close (Focus Trap)
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';

            // Focus Trap implementation
            const handleFocusTrap = (e: KeyboardEvent) => {
                if (e.key === 'Tab' && menuRef.current) {
                    const focusable = menuRef.current.querySelectorAll<HTMLElement>(
                        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
                    );
                    if (focusable.length === 0) return;
                    const first = focusable[0]!;
                    const last = focusable[focusable.length - 1]!;

if (e.shiftKey && document.activeElement === first) {
                        e.preventDefault();
                        last.focus();
                    } else if (!e.shiftKey && document.activeElement === last) {
                        e.preventDefault();
                        first.focus();
                    }
                }
            };

            const handleKeyDown = (e: KeyboardEvent) => {
                if (e.key === 'Escape') onClose();
                handleFocusTrap(e);
            };

            window.addEventListener('keydown', handleKeyDown);

            // Auto-focus first element
            const timer = setTimeout(() => {
                menuRef.current?.querySelector<HTMLElement>('button, [href]')?.focus();
            }, 100);

            return () => {
                window.removeEventListener('keydown', handleKeyDown);
                clearTimeout(timer);
            };
        } else {
            document.body.style.overflow = '';
        }
    }, [isOpen, onClose]);

    useEffect(() => {
        if (user) {
            checkIsAdmin(user.id).then(res => setIsAdmin(res)).catch(() => setIsAdmin(false));
        } else {
            setIsAdmin(false);
        }
    }, [user]);

return (
        <div
            ref={menuRef}
            className={cn(
                'transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] md:hidden glass-premium overflow-y-auto overflow-x-hidden relative z-50',
                isOpen ? 'max-h-[85vh] opacity-100 translate-y-0' : 'max-h-0 opacity-0 -translate-y-4'
            )}
        >
            <nav className="p-4 space-y-2">
                {/* SearchBar en móvil (Alto z-index local) */}
                <div className="sm:hidden pb-4 relative z-[60]">
                    <SearchBar />
                </div>

{isAdmin && (
                    <Link
                        to="/admin"
                        onClick={onClose}
                        className="flex items-center justify-between gap-3 rounded-2xl bg-emerald-500/10 p-4 text-sm font-bold text-emerald-400 border border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.1)] transition-all active:scale-95"
                    >
                        <div className="flex items-center gap-3">
