                            ))}
                        </div>
                    )}
                </motion.div>

{/* Auth: móvil */}
                <div className="pt-2">
                    {isAuthenticated ? (
                        <button
                            onClick={() => { signOut(); onClose(); }}
                            className="flex w-full items-center justify-center gap-2 rounded-xl bg-red-500/10 px-4 py-3.5 text-sm font-bold text-red-400 hover:bg-red-500/20 transition-all active:scale-95"
