export function NotificationCenter({ isOpen, onClose }: NotificationCenterProps) {
    const ref = useRef<HTMLDivElement>(null);
    const notifications = useNotificationsStore((s) => s.notifications);
    const markAsRead = useNotificationsStore((s) => s.markAsRead);
    const markAllAsRead = useNotificationsStore((s) => s.markAllAsRead);
    const clearAll = useNotificationsStore((s) => s.clearAll);

    // Cerrar con click fuera
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (ref.current && !ref.current.contains(event.target as Node)) {
                onClose();
            }
        }
        if (isOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isOpen, onClose]);

    const unreadCount = notifications.filter((n) => !n.read).length;

return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    ref={ref}
                    initial={{ opacity: 0, y: -10, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: -10, scale: 0.95 }}
                    transition={{ type: 'spring', stiffness: 400, damping: 30 }}
                    className="absolute right-0 top-full z-40 mt-3 w-80 max-w-[calc(100vw-2rem)] sm:w-96 origin-top-right rounded-3xl vsm-border bg-[#111]/90 backdrop-blur-3xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] overflow-hidden"
                >
                    {/* Header */}
                    <div className="flex items-center justify-between border-b border-[rgb(var(--border-primary)/0.06)] bg-white/5 px-5 py-4">
                        <div className="flex items-center gap-2">
                            <Bell className="h-4 w-4 text-theme-secondary" />
                            <h3 className="text-sm font-bold text-theme-primary tracking-wide">Notificaciones</h3>
                            {unreadCount > 0 && (
                                <motion.span 
                                    initial={{ scale: 0 }} 
                                    animate={{ scale: 1 }}
                                    className="rounded-full bg-accent-primary/20 vsm-border px-2 py-0.5 text-xs font-black tracking-widest uppercase text-blue-400"
                                >
                                    {unreadCount} nuevas
                                </motion.span>
                            )}
                        </div>
                        <div className="flex items-center gap-1">
                            <motion.button
                                whileHover={{ scale: 1.1, backgroundColor: 'rgba(255,255,255,0.1)' }}
                                whileTap={{ scale: 0.9 }}
                                onClick={markAllAsRead}
                                title="Marcar todas como leídas"
                                className="rounded-lg p-1.5 text-theme-secondary transition-colors"
                            >
                                <Check className="h-4 w-4" />
                            </motion.button>
                            <motion.button
                                whileHover={{ scale: 1.1, backgroundColor: 'rgba(239,68,68,0.1)' }}
                                whileTap={{ scale: 0.9 }}
                                onClick={clearAll}
                                title="Limpiar todo"
                                className="rounded-lg p-1.5 text-theme-secondary hover:text-red-400 transition-colors"
                            >
                                <Trash2 className="h-4 w-4" />
                            </motion.button>
                            <motion.button
                                whileHover={{ scale: 1.1 }}
                                onClick={onClose}
                                className="rounded-lg p-1.5 text-theme-secondary sm:hidden"
                            >
                                <X className="h-4 w-4" />
                            </motion.button>
                        </div>
                    </div>

