const MAX_SEARCH_RESULTS = 5;

interface SearchBarProps {
    className?: string;
}

/** Escapa caracteres especiales de regex para evitar inyección */

function escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export const SearchBar = ({ className }: SearchBarProps = {}) => {
    const [query, setQuery] = useState('');
    const [isOpen, setIsOpen] = useState(false);
    const [selectedIndex, setSelectedIndex] = useState(-1);
    const [recentSearches, setRecentSearches] = useState<string[]>([]);
    const [isVoiceOpen, setIsVoiceOpen] = useState(false);

    const searchRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const { mutateAsync: processTranscript } = useVoiceIntelligence();
    const { triggerSensory } = useStorefrontTactical();
    const navigate = useNavigate();

    // Búsqueda vía hook (debounce + TanStack Query incluidos)
    const { data: searchData, isLoading } = useSearch(query);
    const [semanticResults, setSemanticResults] = useState<Product[]>([]);
    const [isSemanticLoading, setIsSemanticLoading] = useState(false);
    const { data: allCategories = [] } = useCategories();

    // 🎙️ Gestión de Voz (Wave 133)
    // Se integra con useVoiceSearch para la captura y VoiceIntelligence para el procesamiento semántico.
    const { isListening, transcript, error: voiceError, startListening, stopListening } = useVoiceSearch({
        onResult: async (text) => {
            // Decisión inteligente: si la frase es larga, usamos IA. Si es corta, búsqueda directa.
            const shouldAIProcess = text.split(' ').length > 2;

if (shouldAIProcess) {
                setTimeout(async () => {
                    const { searchQuery } = await processTranscript(text);
                    setQuery(searchQuery);
                    setIsVoiceOpen(false);
                    setTimeout(() => handleSubmitForm(searchQuery), 200);
                }, 800);
            } else {
                setQuery(text);
                setTimeout(() => {
                    setIsVoiceOpen(false);
                    handleSubmitForm(text);
                }, 800);
            }
        }
    });

    const products = useMemo(
        () => {
            const basic = (searchData ?? []).slice(0, MAX_SEARCH_RESULTS);
            if (semanticResults.length > 0) {
                const combined = [...basic];
                semanticResults.forEach(p => {
                    if (!combined.find(c => c.id === p.id)) combined.push(p);
                });
                return combined.slice(0, MAX_SEARCH_RESULTS + 2);
            }
            return basic;
        },
        [searchData, semanticResults],
    );

// Filtrar categorías que coincidan con la búsqueda
    const categories = useMemo(() => {
        const normalizedQuery = query.toLowerCase().trim();
        return allCategories
            .filter(cat => 
                cat.name.toLowerCase().includes(normalizedQuery) || 
                cat.slug.toLowerCase().includes(normalizedQuery)
            )
            .slice(0, 3);
    }, [allCategories, query]);

    // Cargar búsquedas recientes de localStorage
    useEffect(() => {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            try { setRecentSearches(JSON.parse(saved)); } catch { /* corrupted */ }
        }
    }, []);

    /** Guardar búsqueda en el historial reciente */
    const saveRecentSearch = useCallback((searchQuery: string) => {
        const trimmed = searchQuery.trim();
        if (!trimmed) return;

        const updated = [
            trimmed,
            ...recentSearches.filter((s) => s !== trimmed),
        ].slice(0, MAX_RECENT_SEARCHES);

        setRecentSearches(updated);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    }, [recentSearches]);

    /** Limpiar todo el historial */
    const clearRecentSearches = useCallback(() => {
        setRecentSearches([]);
        localStorage.removeItem(STORAGE_KEY);
    }, []);

/** 
     * Procesa la navegación final y el guardado en el historial.
     * @param searchQuery - El término de búsqueda final.
     */
    const handleSubmitForm = (searchQuery: string) => {
        if (searchQuery.trim()) {
            saveRecentSearch(searchQuery);
            navigate(`/buscar?q=${encodeURIComponent(searchQuery)}`);
            setIsOpen(false);
            setQuery('');
            inputRef.current?.blur();
        }
    };

    /** 
     * Handlers para el envío del formulario (Legacy HTML form support)
     */
    const handleSubmit = (e?: React.FormEvent) => {
        e?.preventDefault();
        handleSubmitForm(query);
    };

    /**
     * Búsqueda Semántica: Utiliza IA para encontrar productos por contexto,
     * no solo por coincidencia de palabras exactas.
     */
    const handleSemanticSearch = async () => {
        if (!query.trim() || isSemanticLoading) return;
        setIsSemanticLoading(true);
        triggerSensory('nav-click');
        try {
            const results = await conciergeService.semanticSearch(query);
            setSemanticResults(results);
            if (results.length > 0) {
                triggerSensory('success-toast');
            } else {
                triggerSensory('voice-error');
            }
        } catch (_error) {
            triggerSensory('voice-error');
        } finally {
            setIsSemanticLoading(false);
        }
    };

/** Click en búsqueda reciente */
    const handleRecentClick = (search: string) => {
        setQuery(search);
        inputRef.current?.focus();
    };

    /** Navegación por teclado en el dropdown */
    const handleKeyDown = (e: React.KeyboardEvent) => {
        const totalItems = products.length;

        switch (e.key) {
            case 'ArrowDown':
                e.preventDefault();
                setSelectedIndex((prev) => (prev < totalItems - 1 ? prev + 1 : prev));
                break;
            case 'ArrowUp':
                e.preventDefault();
                setSelectedIndex((prev) => (prev > 0 ? prev - 1 : -1));
                break;
            case 'Enter':
                if (selectedIndex >= 0) {
                    e.preventDefault();
                    const product = products[selectedIndex];
                    if (product) {
                        saveRecentSearch(query);
                        navigate(`/${product.section}/${product.slug}`);
                    }
                    setIsOpen(false);
                    setQuery('');
                } else if (query.trim()) {
                    handleSubmit();
                }
                break;
            case 'Escape':
                setIsOpen(false);
                inputRef.current?.blur();
                break;
        }
    };

// Cerrar al hacer clic fuera
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    /** Resalta el texto que coincide con la búsqueda (con escape de regex) */
    const highlightText = (text: string, highlight: string) => {
        if (!highlight.trim()) return text;

        const regex = new RegExp(`(${escapeRegex(highlight)})`, 'gi');
        const parts = text.split(regex);

        return parts.map((part, i) =>
            regex.test(part) ? (
                <mark key={i} className="bg-vape-500/30 text-white font-semibold rounded-sm">
                    {part}
                </mark>
            ) : (
                part
            )
        );
    };

    const hasResults = products.length > 0 || categories.length > 0;
    const showRecent = isOpen && !query && recentSearches.length > 0;
    const showAIHints = isOpen && !query && recentSearches.length === 0;
    const showResults = isOpen && query && hasResults;
    const showAIInsight = isOpen && query && query.length > 2;
    const showEmpty = isOpen && query && !hasResults && !isLoading;

const aiSuggestions = [
        "Vapes desechables más vendidos",
        "E-liquids de menta y frutales",
        "Ofertas relámpago del día",
        "Nuevos accesorios premium"
    ];

    return (
        <div ref={searchRef} role="search" aria-label="Buscar productos" className={cn("relative w-full", className)}>
            {/* Search Input */}
            <form onSubmit={handleSubmit} className="relative group flex items-center w-full h-full">
                {/* ✨ Aura de Foco (Aura Effect) */}
                <motion.div 
                    animate={isOpen ? {
                        opacity: [0.4, 0.7, 0.4],
                        scale: [1, 1.02, 1],
                    } : { opacity: 0 }}
                    transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
                    className="absolute -inset-1 rounded-full bg-gradient-to-r from-accent-primary/40 to-blue-500/40 blur-md pointer-events-none z-0" 
                />

{/* Right side: shortcut + clear + search CTA button */}
                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-2 z-10">
                    <button
                        type="button"
