 */

export const SafetyProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const { isEmergency, checkHealth } = useEmergencyMode();

    const value = useMemo(() => ({
        isEmergency,
        checkHealth
    }), [isEmergency, checkHealth]);

    return (
        <SafetyContext.Provider value={value}>
