describe('useStorefrontPaymentReentry', () => {
    const assignMock = vi.fn();

    const pendingOrder = {
        id: 'order-1',
        order_number: 'VSM-001',
        customer_id: 'user-1',
        items: [{ product_id: 'prod-1', name: 'Item', price: 150, quantity: 1 }],
        subtotal: 150,
        shipping_cost: 0,
        discount: 0,
        total: 150,
        status: 'pending',
        payment_method: 'mercadopago',
        payment_status: 'pending',
        shipping_address_id: null,
        billing_address_id: null,
        tracking_notes: null,
        whatsapp_sent: false,
        whatsapp_sent_at: null,
        created_at: '2026-03-26T00:00:00.000Z',
        updated_at: '2026-03-26T00:00:00.000Z',
    };

    beforeEach(() => {
        navigateMock.mockReset();
        warningMock.mockReset();
        errorMock.mockReset();
        getOrderByIdMock.mockReset();
        createPaymentMock.mockReset();
        assignMock.mockReset();
        Object.defineProperty(window, 'location', {
            configurable: true,
            value: { assign: assignMock },
        });
    });

    it('revalidates persisted truth before reopening Mercado Pago', async () => {
        getOrderByIdMock.mockResolvedValue(pendingOrder);
        createPaymentMock.mockResolvedValue({
            init_point: 'https://mp.test/pay/order-1',
            preference_id: 'pref-1',
        });

        const { result } = renderHook(() => useStorefrontPaymentReentry());

await act(async () => {
            await result.current.continuePayment(pendingOrder);
        });

        await waitFor(() => {
            expect(getOrderByIdMock).toHaveBeenCalledWith('order-1');
            expect(createPaymentMock).toHaveBeenCalledWith('order-1');
            expect(assignMock).toHaveBeenCalledWith('https://mp.test/pay/order-1');
        });
    });

    it('blocks re-entry when fresh persisted truth is no longer payable', async () => {
        getOrderByIdMock.mockResolvedValue({
            ...pendingOrder,
            payment_status: 'paid',
            status: 'processing',
        });

        const { result } = renderHook(() => useStorefrontPaymentReentry());

        await act(async () => {
            await result.current.continuePayment(pendingOrder);
        });

        await waitFor(() => {
            expect(createPaymentMock).not.toHaveBeenCalled();
            expect(warningMock).toHaveBeenCalledWith(
                'Pago no disponible',
                'El pago de esta orden ya figura confirmado. Revisa el detalle persistido en lugar de intentar abrir otro cobro.',
            );
            expect(navigateMock).toHaveBeenCalledWith('/orders/order-1');
        });
    });

    it('clears continuingOrderId when fresh persisted truth blocks re-entry', async () => {
        getOrderByIdMock.mockResolvedValue({
            ...pendingOrder,
            payment_status: 'paid',
            status: 'processing',
        });

const { result } = renderHook(() => useStorefrontPaymentReentry());

        await act(async () => {
            await result.current.continuePayment(pendingOrder);
        });

        await waitFor(() => {
            expect(result.current.continuingOrderId).toBeNull();
            expect(createPaymentMock).not.toHaveBeenCalled();
        });
    });

    it('clears continuingOrderId when fresh order is not found', async () => {
        getOrderByIdMock.mockResolvedValue(null);

        const { result } = renderHook(() => useStorefrontPaymentReentry());

        await act(async () => {
            await result.current.continuePayment(pendingOrder);
        });

        await waitFor(() => {
            expect(result.current.continuingOrderId).toBeNull();
            expect(warningMock).toHaveBeenCalledWith(
                'Pedido no disponible',
                'No pudimos confirmar el estado actual del pedido. Revisa el detalle persistido antes de intentar otro pago.',
            );
            expect(navigateMock).toHaveBeenCalledWith('/orders');
        });
    });
});

describe('useSwipe Hook', () => {
    it('debería registrar y limpiar los event listeners correctamente', () => {
        const ref = createRef<HTMLElement>();
        const mockElement = {
            addEventListener: vi.fn(),
            removeEventListener: vi.fn(),
        } as unknown as HTMLElement;

        // @ts-expect-error - Forzamos el ref para la prueba
        ref.current = mockElement;

        const { unmount } = renderHook(() => useSwipe(ref, {}));

        // Verificar que se agregaron los listeners
        expect(mockElement.addEventListener).toHaveBeenCalledWith('touchstart', expect.any(Function), { passive: true });
        expect(mockElement.addEventListener).toHaveBeenCalledWith('touchmove', expect.any(Function), { passive: true });
        expect(mockElement.addEventListener).toHaveBeenCalledWith('touchend', expect.any(Function));

        // Desmontar y verificar limpieza
        unmount();
        expect(mockElement.removeEventListener).toHaveBeenCalledWith('touchstart', expect.any(Function));
        expect(mockElement.removeEventListener).toHaveBeenCalledWith('touchmove', expect.any(Function));
        expect(mockElement.removeEventListener).toHaveBeenCalledWith('touchend', expect.any(Function));
    });

    // Nota: Simular eventos táctiles completos en JSDOM es complejo y propenso a errores.
    // La prueba principal aquí es asegurar que el hook se monta/desmonta sin errores
    // y maneja correctamente las referencias nulas.

it('no debería fallar si el ref es null', () => {
        const ref = createRef<HTMLElement>();
        const { result } = renderHook(() => useSwipe(ref, {}));
        expect(result.current).toBeUndefined(); // El hook no retorna nada
    });
});

