type CesarinTabId = NavTab['id'];
type CesarinTabGroup = 'monitor' | 'review' | 'configure' | 'lab';

interface CesarinTabDefinition {
    id: CesarinTabId;
    label: string;
    title: string;
    description: string;
    operatorCue: string;
    translator?: string[];
    icon: NavTab['icon'];
