export function AdminCustomers() {
    const [search, setSearch] = useState('');
    const [page, setPage] = useState(1);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { customers, isLoading } = useAdminCustomers();

    const filtered = useMemo(() => {
        if (!search.trim()) return customers;
        const q = search.toLowerCase();
        return customers.filter((c: AdminCustomer) =>
            c.full_name?.toLowerCase().includes(q) ||
            c.phone?.toLowerCase().includes(q) ||
            c.whatsapp?.toLowerCase().includes(q) ||
            c.id?.toLowerCase().includes(q)
        );
    }, [customers, search]);

    const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
    const safePage = Math.min(page, totalPages);
    const paginated = paginateItems(filtered, safePage, PAGE_SIZE);
    const startItem = (safePage - 1) * PAGE_SIZE + 1;
    const endItem = Math.min(safePage * PAGE_SIZE, filtered.length);

if (isLoading) {
        return (
            <div className="max-w-[1400px] mx-auto space-y-6 sm:space-y-8 animate-pulse">
                <div className="h-20 w-full mb-4 bg-white/5 rounded-[2.5rem]" />
                <div className="h-32 w-full mb-4 bg-white/5 rounded-[2.5rem]" />
                <div className="bg-[#13141f] rounded-[2.5rem] p-8 border border-white/5 space-y-4">
                    <div className="h-8 w-48 bg-white/10 rounded-xl mb-8" />
                    {[1, 2, 3, 4, 5].map(i => (
                        <div key={i} className="h-16 w-full bg-white/5 rounded-2xl" />
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div className="max-w-[1400px] mx-auto space-y-6 sm:space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header del Módulo */}
            <CustomerDirectoryHeader onNewCustomer={() => setIsModalOpen(true)} />

            {/* Estadísticas Globales */}
            <CustomerDirectoryStats customers={customers} />

{filtered.length === 0 ? (
                    <AdminEmptyState
                        icon={Users}
                        title="No se encontraron clientes"
                        description="Intenta con otra búsqueda o registra uno nuevo."
                        className="py-16 mx-2 sm:mx-0"
                    />
                ) : (
                    <div className="space-y-6">
                        {/* Tabla de Resultados (Lego) */}
                        <div className="bg-black/20 rounded-3xl border border-white/5 overflow-hidden">
                            <CustomerList customers={paginated} />
                        </div>

                        {/* Paginación */}
                        {filtered.length > PAGE_SIZE && (
                            <div className="px-2 sm:px-0 flex justify-end">
                                <Pagination
                                    currentPage={safePage}
                                    totalPages={totalPages}
                                    onPageChange={(p) => setPage(p)}
                                    itemsLabel={`${startItem}-${endItem} de ${filtered.length}`}
                                />
                            </div>
                        )}
                    </div>
                )}
            </div>

{/* Modal para Crear Cliente */}
            <CustomerFormModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                onSuccess={() => setIsModalOpen(false)}
            />
        </div>
    );
}

