        const swapOrder = swap.order ?? swapIndex;
        newSliders[index] = { ...current, order: swapOrder };
        newSliders[swapIndex] = { ...swap, order: currentOrder };

// Reordenar el array
        newSliders.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

