    const mostUsed = tags.length > 0
      ? [...tags].sort((a, b) => (b.product_count || 0) - (a.product_count || 0))[0]
      : null;
    return { total, productsTagged, mostUsedTag: mostUsed?.label ?? null };
  }, [tags]);

  // Pagination
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const paginated = paginateItems(filtered, safePage, PAGE_SIZE);
  const startItem = (safePage - 1) * PAGE_SIZE + 1;
  const endItem = Math.min(safePage * PAGE_SIZE, filtered.length);

  // Modal handlers
  const handleOpenCreate = () => {
    setEditingName(null);
    setForm(EMPTY_FORM);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (tag: ProductTag) => {
    setEditingName(tag.name);
    setForm({ label: tag.label, name: tag.name });
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingName(null);
    setForm(EMPTY_FORM);
  };

  const handleSubmit = () => {
    if (!form.label.trim() || !form.name.trim()) {
      notifyError('Validación', 'El nombre de la etiqueta es obligatorio.');
      return;
    }

    if (editingName) {
      renameMutation.mutate({ oldName: editingName, newLabel: form.label });
    } else {
      createMutation.mutate({ name: form.name, label: form.label });
    }
  };

const handleDelete = async (name: string) => {
    const tag = tags.find((t) => t.name === name);
    if (!tag) return;

    if ((tag.product_count || 0) > 0) {
      notifyError(
        'Etiqueta en uso',
        `No se puede eliminar: está asociada a ${tag.product_count} producto(s)`
      );
      return;
    }

    const isConfirmed = await confirm({
      title: `¿Eliminar la etiqueta "${tag.label}"?`,
      description: 'Esta acción no se puede deshacer.',
      confirmText: 'Sí, eliminar',
      cancelText: 'Cancelar',
      type: 'danger'
    });

    if (isConfirmed) {
      deleteMutation.mutate(name);
    }
  };

  // Loading state
  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
        <div className="relative">
          <div className="absolute inset-0 bg-accent-primary/20 blur-xl rounded-full" />
          <Loader2 className="h-10 w-10 animate-spin text-accent-primary relative z-10" />
        </div>
        <p className="text-theme-secondary font-medium tracking-wide animate-pulse">
          Cargando etiquetas...
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-20 max-w-7xl mx-auto px-4 sm:px-6">
      <TagsHeader onNew={handleOpenCreate} />

      <TagsStats
        total={stats.total}
        productsTagged={stats.productsTagged}
        mostUsedTag={stats.mostUsedTag}
      />

export function AdminTestimonials() {
    const { error, info } = useNotification();
    const { confirm } = useConfirm();

    // State
    const [search, setSearch] = useState('');
    const [filterSection, setFilterSection] = useState<string>('all');
    const [editingId, setEditingId] = useState<string | null>(null);
    const [isCreating, setIsCreating] = useState(false);
    const [form, setForm] = useState<TestimonialFormData>(EMPTY_FORM);
    const [page, setPage] = useState(1);

    // Unified Hook
    const { 
        testimonials, 
        isLoading, 
        createTestimonial, 
        updateTestimonial, 
        deleteTestimonial, 
        toggleFeatured, 
        toggleActive, 
        isMutating 
    } = useAdminTestimonials();

    // Filtering & Derived Data
    const filtered = useMemo(() => {
        let result = testimonials;

        if (filterSection !== 'all') {
            if (filterSection === 'general') {
                result = result.filter((t: Testimonial) => !t.section);
            } else {
                result = result.filter((t: Testimonial) => t.section === filterSection);
            }
        }

if (search.trim()) {
            const q = search.toLowerCase();
            result = result.filter(
                (t: Testimonial) =>
                    t.customer_name?.toLowerCase().includes(q) ||
                    t.body?.toLowerCase().includes(q) ||
                    t.title?.toLowerCase().includes(q) ||
                    t.customer_location?.toLowerCase().includes(q),
            );
        }

        return result;
    }, [testimonials, search, filterSection]);

    const stats = useMemo(() => {
        const total = testimonials.length;
        const active = testimonials.filter((t: Testimonial) => t.is_active).length;
        const featured = testimonials.filter((t: Testimonial) => t.is_featured).length;
        const avgRating = total > 0
            ? (testimonials.reduce((s: number, t: Testimonial) => s + t.rating, 0) / total).toFixed(1)
            : '0';
        const vape = testimonials.filter((t: Testimonial) => t.section === 'vape').length;
        const herbal = testimonials.filter((t: Testimonial) => t.section === '420').length;
        return { total, active, featured, avgRating, vape, herbal };
    }, [testimonials]);

// Pagination Calculation
    const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
    const safePage = Math.min(page, totalPages);
    const paginated = paginateItems(filtered, safePage, PAGE_SIZE);
    const startItem = (safePage - 1) * PAGE_SIZE + 1;
    const endItem = Math.min(safePage * PAGE_SIZE, filtered.length);

    // Handlers
    const resetForm = () => {
        setForm(EMPTY_FORM);
        setEditingId(null);
        setIsCreating(false);
    };

    const handleEdit = (t: Testimonial) => {
        setForm({
            customer_name: t.customer_name,
            customer_location: t.customer_location ?? '',
            avatar_url: t.avatar_url ?? '',
            rating: t.rating,
            title: t.title ?? '',
            body: t.body,
            section: t.section ?? '',
            category_id: t.category_id ?? '',
            product_id: t.product_id ?? '',
            verified_purchase: t.verified_purchase,
            is_featured: t.is_featured,
            is_active: t.is_active,
            sort_order: t.sort_order,
            review_date: (t.review_date ?? new Date().toISOString()).slice(0, 10),
        });
        setEditingId(t.id);
        setIsCreating(false);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

const handleDuplicate = (t: Testimonial) => {
        setForm({
            customer_name: `${t.customer_name} (Copia)`,
            customer_location: t.customer_location ?? '',
            avatar_url: t.avatar_url ?? '',
            rating: t.rating,
            title: t.title ?? '',
            body: t.body,
            section: t.section ?? '',
            category_id: t.category_id ?? '',
            product_id: t.product_id ?? '',
            verified_purchase: t.verified_purchase,
            is_featured: false,
            is_active: true,
            sort_order: t.sort_order + 1,
            review_date: new Date().toISOString().slice(0, 10),
        });
        setEditingId(null);
        setIsCreating(true);
        window.scrollTo({ top: 0, behavior: 'smooth' });
        info("Aviso", "Testimonio duplicado. ¡Recuerda guardarlo!");
    };

    const handleDelete = async (id: string) => {
        const isConfirmed = await confirm({
            title: '¿Eliminar testimonio permanentemente?',
            description: 'Esta acción no se puede deshacer.',
            confirmText: 'Sí, eliminar',
            cancelText: 'Cancelar',
            type: 'danger'
        });
        if (isConfirmed) {
            deleteTestimonial(id);
        }
    };

const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!form.customer_name.trim() || !form.body.trim()) {
            error("Error", "El nombre y el texto de la reseña son obligatorios.");
            return;
        }
        if (editingId) {
            await updateTestimonial(editingId, form);
        } else {
            await createTestimonial(form);
        }
        resetForm();
    };

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
                <div className="relative">
                    <div className="absolute inset-0 bg-accent-primary/20 blur-xl rounded-full"></div>
                    <Loader2 className="h-10 w-10 animate-spin text-accent-primary relative z-10" />
                </div>
                <p className="text-theme-secondary font-medium tracking-wide animate-pulse">Cargando testimonios...</p>
            </div>
        );
    }

    return (
        <div className="space-y-8 pb-20 max-w-7xl mx-auto px-4 sm:px-6">
            <TestimonialsHeader
                onNew={() => {
                    resetForm();
                    setIsCreating(true);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                }}
            />

            <TestimonialsStats stats={stats} />

{(isCreating || editingId) && (
                <div className="animate-in fade-in slide-in-from-top-4 duration-300">
                    <TestimonialsForm
                        form={form}
                        setForm={setForm}
                        onSubmit={handleSubmit}
                        onCancel={resetForm}
                        editingId={editingId}
                        isPending={isMutating}
                    />
                </div>
            )}

            <div className="bg-[#181825]/50 rounded-3xl p-6 border border-white/5 space-y-6">
                <TestimonialsFilters
                    search={search}
                    onSearchChange={(val) => { setSearch(val); setPage(1); }}
                    filterSection={filterSection}
                    onFilterSectionChange={(val) => { setFilterSection(val); setPage(1); }}
                />

                <TestimonialsGrid
                    testimonials={paginated}
                    onEdit={handleEdit}
                    onDuplicate={handleDuplicate}
                    onDelete={handleDelete}
                    onToggleFeatured={(id, v) => toggleFeatured(id, v)}
                    onToggleActive={(id, v) => toggleActive(id, v)}
                />

{filtered.length > PAGE_SIZE && (
                    <div className="pt-6 border-t border-white/5">
                        <Pagination
                            currentPage={safePage}
                            totalPages={totalPages}
                            onPageChange={(p) => {
                                setPage(p);
                                window.scrollTo({ top: 0, behavior: 'smooth' });
                            }}
                            itemsLabel={`${startItem}–${endItem} de ${filtered.length} testimonios`}
                        />
                    </div>
                )}
            </div>
        </div>
    );
}

