import type { Tier } from '@/services';

interface TierConfigItem {
    id: string;
    name?: string;
    label?: string;
    threshold?: number;
    minSpent?: number;
    benefits?: string[];
}

export function Loyalty() {
    const { user, profile } = useAuth();
    const { data: settings } = useStoreSettings();
    const { data: points = 0, isLoading: loadingPoints } = usePointsBalance(user?.id);
    const { data: history = [], isLoading: loadingHistory } = usePointsHistory(user?.id);
    const { data: tierData, isLoading: loadingTier } = useTierProgress(user?.id);
    const { data: referralStats, isLoading: loadingReferrals } = useReferralStats(user?.id);
    const redeemMutation = useRedeemPoints();
    const notify = useNotification();

    useEffect(() => {
        document.title = 'Programa de Lealtad | VSM Store';
        return () => { document.title = 'VSM Store'; };
    }, []);

    const isLoading = loadingPoints || loadingTier;

    if (isLoading) {
        return (
            <div className="flex min-h-[60vh] items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-vape-500" />
            </div>
        );
    }

    const currentTier = tierData?.currentTier ?? 'bronze';

    const loyaltyConfig = settings?.loyalty_config || {
        points_per_currency: 0.1,
        currency_per_point: 0.1,
        min_points_to_redeem: 100,
        max_points_per_order: 1000,
        points_expiry_days: 365,
        enable_loyalty: true
    };

    const canRedeem = points >= loyaltyConfig.min_points_to_redeem;

const handleRedeem = async () => {
        if (!user || !canRedeem) return;
        try {
            const { discount } = await redeemMutation.mutateAsync({ customerId: user.id, points: loyaltyConfig.min_points_to_redeem });
            notify.success('¡V-Coins canjeados!', `Has canjeado ${loyaltyConfig.min_points_to_redeem} V-Coins por un descuento de $${discount}. Se aplicará en tu próxima compra.`);
        } catch {
            notify.error('Error', 'No se pudieron canjear los V-Coins. Intenta de nuevo.');
        }
    };

    return (
        <div className="container-vsm py-8 space-y-6">
            {/* Header */}
            <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-yellow-500/10">
                    <Award className="h-5 w-5 text-yellow-400" />
                </div>
                <h1 className="text-xl font-bold text-theme-primary">Programa de Lealtad</h1>
            </div>

            {/* ─── SECCIÓN REFERIDOS ─── */}
            <ReferralCard
                referralCode={profile?.referral_code || ''}
                stats={referralStats || { count: 0, completed: 0, pointsEarned: 0 }}
                loading={loadingReferrals}
            />

            <ApplyReferralForm />

            {/* 🎯 SMART QUESTS (WAVE 110) */}
            <SmartQuests />

{tierData?.nextTier && (
                    <div className="space-y-2">
                        <ProgressBar
                            value={tierData.progress}
                            tier={currentTier}
                            height="md"
                            showPercentage
                        />
                        <p className="text-xs text-theme-secondary">
                            Gasta <strong className="text-theme-secondary">{formatPrice(tierData.remaining)}</strong> más para alcanzar{' '}
                            <TierBadge
                                tier={tierData.nextTier as Tier}
                                size="sm"
                                customLabel={settings?.loyalty_tiers_config?.find((t: TierConfigItem) => t.id === tierData.nextTier)?.name}
                            />
                        </p>
                    </div>
                )}

{/* Historial */}
                <div className="pt-3 border-t border-theme-strong">
                    <p className="text-xs font-medium text-theme-secondary mb-3">Historial de V-Coins</p>
                    {loadingHistory ? (
                        <Loader2 className="h-4 w-4 animate-spin text-accent-primary mx-auto" />
                    ) : history.length === 0 ? (
                        <p className="text-xs text-accent-primary text-center py-4">Aún no has acumulado V-Coins</p>
                    ) : (
                        <div className="space-y-1 max-h-64 overflow-y-auto scrollbar-thin">
                            {history.map((tx) => (
                                <div key={tx.id} className="flex items-center justify-between py-2 px-2 rounded-lg hover:bg-theme-secondary/30">
                                    <div>
                                        <p className="text-xs text-theme-secondary">{tx.description}</p>
                                        <p className="text-xs text-accent-primary">
                                            {new Date(tx.created_at).toLocaleDateString('es-MX', {
                                                day: 'numeric', month: 'short', year: 'numeric',
                                            })}
                                        </p>
                                    </div>
                                    <span className={cn(
                                        'text-sm font-bold',
                                        tx.points > 0 ? 'text-herbal-400' : 'text-red-400'
                                    )}>
                                        {tx.points > 0 ? '+' : ''}{tx.points}
                                    </span>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>

{/* ─── SECCIÓN 3: Beneficios por tier ─── */}
            <div className="space-y-4">
                <h2 className="text-[10px] font-black text-theme-tertiary uppercase tracking-[0.2em] opacity-60 px-1">
                    Niveles del programa
                </h2>
                <div className="grid gap-4 sm:grid-cols-2">
                    {(settings?.loyalty_tiers_config || Object.entries(LOYALTY_TIERS).map(([id, t]) => ({ ...t, id }))).map((tierItem: TierConfigItem) => {
                        const tierId = tierItem.id as Tier;
                        const isCurrent = tierId === currentTier;
                        const tierName = tierItem.name || tierItem.label;
                        const threshold = (tierItem.threshold !== undefined ? tierItem.threshold : tierItem.minSpent) ?? 0;

return (
                            <div
                                key={tierId}
                                className={cn(
                                    'rounded-2xl border p-5 space-y-4 transition-all duration-500 backdrop-blur-xl group',
                                    isCurrent
                                        ? 'border-vape-500/30 bg-vape-500/10 ring-1 ring-vape-500/20 shadow-2xl shadow-vape-500/10'
                                        : 'border-white/5 bg-white/[0.02] hover:bg-white/[0.05] hover:border-white/10'
                                )}
                            >
                                <div className="flex items-center justify-between">
                                    <TierBadge tier={tierId} size="md" customLabel={tierName} />
                                    {isCurrent && (
                                        <span className="text-[8px] font-black uppercase tracking-widest text-vape-400 bg-vape-400/10 px-2 py-1 rounded-full">Tu nivel</span>
                                    )}
                                </div>
                                {threshold > 0 && (
                                    <p className="text-[10px] font-bold text-accent-primary uppercase tracking-tight">
                                        Desde {formatPrice(threshold)} gastados
                                    </p>
                                )}
                                <ul className="space-y-2">
                                    {(tierItem.benefits || []).map((b: string, i: number) => (
                                        <li key={i} className="flex items-start gap-2 text-[11px] text-theme-secondary group-hover:text-theme-primary transition-colors">
                                            <Star className="h-3 w-3 text-yellow-500 mt-0.5 flex-shrink-0 animate-pulse-slow" /> {b}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
}

