function getPaymentMethodLabel(paymentMethod: string) {
    switch (paymentMethod) {
        case 'cash':
            return 'Efectivo';
        case 'transfer':
            return 'Transferencia';
        case 'mercadopago':
            return 'Mercado Pago';
        case 'card':
            return 'Tarjeta';
        case 'whatsapp':
            return 'WhatsApp';
        default:
            return paymentMethod;
    }
}

