                                        )}
                                    >
                                        {opt.label}
                                    </button>
                                ))}
                            </div>
                        )}

{/* Mobile bottom sheet */}
                        <div className="sm:hidden">
                            <BottomSheet isOpen={sortOpen} onClose={() => setSortOpen(false)} title="Ordenar por">
                                <div className="flex flex-col gap-2">
                                    {SORT_OPTIONS.map(opt => (
                                        <button
                                            key={opt.value}
                                            onClick={() => { setSort(opt.value); setSortOpen(false); }}
                                            className={cn(
                                                'w-full rounded-xl px-4 py-4 text-left text-sm font-medium transition-all',
                                                sort === opt.value
                                                    ? cn(cfg.sortActive, 'border')
                                                    : 'bg-theme-secondary/10 text-theme-secondary border border-transparent hover:bg-theme-secondary/20'
                                            )}
                                        >
                                            {opt.label}
                                        </button>
                                    ))}
                                </div>
                            </BottomSheet>
                        </div>
                    </div>
                </div>

{/* ═══ PRODUCT GRID ═══ */}
                <div ref={gridRef} className="scroll-mt-4">
                    <ProductGrid
                        products={filteredProducts}
                        isLoading={isLoading}
                        onClearFilter={activeCategory ? () => setActiveCategory(null) : undefined}
                    />
                </div>

                {/* ═══ SOCIAL PROOF ═══ */}
                <SectionErrorBoundary name="SocialProof" resetKey={section}>
                    <SocialProof section={section} variant="compact" limit={4} />
                </SectionErrorBoundary>
            </div>
        </div>
    );
}

// Wrapper que distingue entre categoría y producto usando la misma ruta - VSM Store
// Dado que /vape/:slug puede ser una categoría o un producto,
// intentamos primero como categoría; si no existe, renderizamos como producto.

import { useSectionFromPath } from '@/hooks/useSectionFromPath';

/**
 * Resuelve si un slug es categoría o producto.
 * Primero busca categoría por slug; si existe → CategoryPage, si no → ProductDetail.
 */

export function SectionSlugResolver() {
    const { slug } = useParams<{ slug: string }>();
    const section = useSectionFromPath();

    const {
        data: category,
        isLoading,
    } = useCategoryBySlug(slug ?? '', section);

    // Mientras carga, no sabemos aún qué renderizar
    if (isLoading) {
        return (
            <div className="container-vsm py-8">
                <div className="space-y-4 animate-pulse">
                    <div className="h-6 w-40 rounded-lg bg-theme-secondary/50" />
                    <div className="h-10 w-2/3 rounded-lg bg-theme-secondary/50" />
                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
                        {[1, 2, 3, 4].map((i) => (
                            <div key={i} className="h-64 rounded-2xl bg-theme-secondary/40" />
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    // Si encontramos una categoría → CategoryPage
    if (category) {
        return <CategoryPage />;
    }

    // Si no es categoría → ProductDetail
    return <ProductDetail />;
}

