export interface RepoGraphResolvedLink {
    relationship: string;
    weight?: number;
    source: RepoGraphNode;
    target: RepoGraphNode;
}

export interface RepoGraphChunkPreview {
    type: string;
    preview: string;
}

export interface RepoGraphInspector {
    node: RepoGraphNode;
    containerNode: RepoGraphNode | null;
    nodeDirectory: string | null;
    parentLinks: RepoGraphResolvedLink[];
    childLinks: RepoGraphResolvedLink[];
    nearbyNodes: RepoGraphNode[];
    sameContainerNodes: RepoGraphNode[];
    sameTypeNodes: RepoGraphNode[];
    pathLocalNodes: RepoGraphNode[];
    chunkPreviews: RepoGraphChunkPreview[];
}

export interface RepoGraphOverview {
    totalNodes: number;
    totalLinks: number;
    relationshipTypes: string[];
    nodeTypes: string[];
}

function normalizeText(value: string | undefined): string {
    return (value ?? '').toLowerCase();
}

function buildChunkPreview(text: string): string {
    const compact = text.replace(/\s+/g, ' ').trim();
    if (compact.length <= 240) {
        return compact;
    }

    return `${compact.slice(0, 237)}...`;
}

function uniqueNodes(items: RepoGraphNode[]): RepoGraphNode[] {
    const seen = new Set<string>();
    return items.filter((item) => {
        if (seen.has(item.id)) {
            return false;
        }
        seen.add(item.id);
        return true;
    });
}

function resolveLinks(rawLinks: RepoGraphLink[]): RepoGraphResolvedLink[] {
    return rawLinks.flatMap((link) => {
        const source = nodeById.get(link.source);
        const target = nodeById.get(link.target);

        if (!source || !target) {
            return [];
        }

        return [{
            relationship: link.relationship,
            weight: link.weight,
            source,
            target,
        }];
    });
}

function getNodeDirectory(node: RepoGraphNode): string | null {
    const rawPath = node.file_path ?? node.id;
    const normalized = rawPath.replace(/\\/g, '/');
    const lastSlashIndex = normalized.lastIndexOf('/');

    if (lastSlashIndex <= 0) {
        return null;
    }

    return normalized.slice(0, lastSlashIndex);
}

function sortNodesForReview(anchor: RepoGraphNode, candidates: RepoGraphNode[]): RepoGraphNode[] {
    const anchorDirectory = getNodeDirectory(anchor);

    return [...candidates].sort((a, b) => {
        const aDirectory = getNodeDirectory(a);
        const bDirectory = getNodeDirectory(b);
        const aSameDirectory = aDirectory === anchorDirectory ? 0 : 1;
        const bSameDirectory = bDirectory === anchorDirectory ? 0 : 1;

        if (aSameDirectory !== bSameDirectory) {
            return aSameDirectory - bSameDirectory;
        }

        const aPath = a.file_path ?? a.id;
        const bPath = b.file_path ?? b.id;
        return aPath.localeCompare(bPath);
    });
}

export function getRepoGraphOverview(): RepoGraphOverview {
    return {
        totalNodes: nodes.length,
        totalLinks: links.length,
        relationshipTypes: Array.from(new Set(links.map((link) => link.relationship))).sort(),
        nodeTypes: Array.from(new Set(nodes.map((node) => node.type))).sort(),
    };
}

export function getRepoGraphNodeById(nodeId: string | null | undefined): RepoGraphNode | null {
    if (!nodeId) {
        return null;
    }

    return nodeById.get(nodeId) ?? null;
}

export function listRepoGraphNodes(options?: {
    search?: string;
    type?: string;
    limit?: number;
}): RepoGraphNode[] {
    const search = normalizeText(options?.search);
    const type = options?.type;
    const limit = options?.limit ?? 160;

    const filtered = nodes.filter((node) => {
        if (type && node.type !== type) {
            return false;
        }

        if (!search) {
            return true;
        }

        return [
            node.label,
            node.id,
            node.type,
            node.file_path,
            node.description,
        ].some((value) => normalizeText(value).includes(search));
    });

    filtered.sort((a, b) => {
        const aPath = a.file_path ?? a.id;
        const bPath = b.file_path ?? b.id;

        if (aPath === DEFAULT_REPO_GRAPH_NODE_ID) {
            return -1;
        }

        if (bPath === DEFAULT_REPO_GRAPH_NODE_ID) {
            return 1;
        }

        return aPath.localeCompare(bPath);
    });

    return filtered.slice(0, limit);
}

export function getRepoGraphInspector(nodeId: string): RepoGraphInspector | null {
    const node = nodeById.get(nodeId);
    if (!node) {
        return null;
    }

    const parentLinks = resolveLinks(incomingLinks.get(nodeId) ?? []);
    const childLinks = resolveLinks(outgoingLinks.get(nodeId) ?? []);
    const containerNode = parentLinks.find((link) => link.relationship === 'CONTAINS')?.source ?? parentLinks[0]?.source ?? null;
    const nodeDirectory = getNodeDirectory(node);

    const sameContainerNodes = uniqueNodes(
        parentLinks.flatMap((link) => {
            const siblings = outgoingLinks.get(link.source.id) ?? [];
            return siblings
                .map((siblingLink) => nodeById.get(siblingLink.target))
                .filter((candidate): candidate is RepoGraphNode => candidate !== undefined && candidate.id !== nodeId);
        }),
    );

    const sameTypeNodes = sortNodesForReview(
        node,
        uniqueNodes(
            nodes.filter((candidate) => candidate.id !== node.id && candidate.type === node.type),
        ),
    ).slice(0, 12);

    const pathLocalNodes = nodeDirectory
        ? sortNodesForReview(
            node,
            uniqueNodes(
                nodes.filter((candidate) => candidate.id !== node.id && getNodeDirectory(candidate) === nodeDirectory),
            ),
        ).slice(0, 12)
        : [];

    const nearbyNodes = sameContainerNodes.slice(0, 12);

const chunkPreviews = (node.chunks ?? [])
        .filter((chunk) => chunk.text.trim().length > 0)
        .slice(0, 3)
        .map((chunk) => ({
            type: chunk.type ?? 'chunk',
            preview: buildChunkPreview(chunk.text),
        }));

    return {
        node,
        containerNode,
        nodeDirectory,
        parentLinks,
        childLinks,
        nearbyNodes,
        sameContainerNodes: sameContainerNodes.slice(0, 12),
        sameTypeNodes,
        pathLocalNodes,
        chunkPreviews,
    };
}

export type SignalStatusDB =
    | 'revisada'
    | 'descartada'
    | 'convertida_regla'
    | 'convertida_mejora'
    | 'resuelta';

export interface SignalStateRow {
    analytics_id: string;
