 * Obtiene productos bestseller (is_bestseller = true)
 */

export async function getBestsellerProducts(options: { section?: Section; limit?: number } = {}): Promise<Product[]> {
    return getProducts({ 
        section: options.section, 
        filter: 'bestseller', 
