            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: 'models/gemini-embedding-001',
                content: { parts: [{ text }] },
                outputDimensionality: 3072
            })
        })
        const result = await res.json()
        return result.embedding?.values ?? null
    } catch (err) {
        return null
    }
}

